export const newsArticles = [
  N('arctic-melt-season','ecology','2026-09-21','arctic-melt',
    [['NASA Earth Observatory','https://science.nasa.gov/earth/earth-observatory/arctic-melt-season-length-levels-off/']],
    {credit:'NASA Earth Observatory / Michala Garrison',source:'https://science.nasa.gov/earth/earth-observatory/arctic-melt-season-length-levels-off/',license:nasaMedia,
      alt:{sr:'Karta Arktika sa promenama trajanja sezone topljenja od 2010. do 2023.',sl:'Zemljevid Arktike s spremembami trajanja sezone taljenja od 2010 do 2023.',en:'Arctic map showing changes in melt-season length from 2010 to 2023.'},
      caption:{sr:'Promena trajanja sezone topljenja 2010–2023; plava i crvena označavaju suprotne trendove.',sl:'Sprememba trajanja sezone taljenja 2010–2023; modra in rdeča kažeta nasprotna trenda.',en:'Change in melt-season length in 2010–2023; blue and red indicate opposite trends.'},
      inline:{src:'news/arctic-earlier.jpg',credit:'NASA Earth Observatory / Michala Garrison',source:'https://science.nasa.gov/earth/earth-observatory/arctic-melt-season-length-levels-off/',license:nasaMedia,
        alt:{sr:'Karta Arktika sa promenama trajanja sezone topljenja tokom 2000-ih.',sl:'Zemljevid Arktike s spremembami trajanja sezone taljenja v 2000-ih.',en:'Arctic map of melt-season changes during the 2000s.'},
        caption:{sr:'Tokom 2000-ih u velikom delu Arktika sezona topljenja se brzo produžavala.',sl:'V 2000-ih se je sezona taljenja v velikem delu Arktike hitro podaljševala.',en:'During the 2000s, melt seasons lengthened rapidly across much of the Arctic.'}}},
    {
      sr:{slug:'sezona-topljenja-arktickog-leda-usporila-rast',title:'Zašto se sezona topljenja arktičkog leda više ne produžava kao ranije?',lead:'Sateliti pokazuju zastoj u jednom trendu posle 2010. godine, ali arktički led je i dalje mnogo ugroženiji nego pre nekoliko decenija.',take:['Sezona topljenja je oko 40 dana duža nego 1979.','Posle približno 2010. prosečno trajanje sezone se nije mnogo menjalo.','To ne znači da je zagrevanje Arktika prestalo.'],term:'Sezona topljenja — deo godine između početka prolećnog topljenja morskog leda i njegovog ponovnog jesenjeg smrzavanja.',sections:[
        {h:'Šta su sateliti zaista uočili?',p:['Od 1979. istraživači prate kada morski led na Arktiku počinje da se topi i kada se ponovo zamrzava. Nova analiza podataka do 2023. pokazuje da je sezona topljenja danas približno 40 dana duža nego na početku merenja. Najveći deo tog produženja nastao je pre 2010. godine; posle toga prosečna dužina sezone nije nastavila da raste istim tempom.','To je zanimljiv rezultat jer se arktički vazduh i dalje brzo zagreva. Naučnici zato ne govore o „oporavku” leda, već o promeni načina na koji se različiti uticaji smenjuju. Jedne godine oluje, oblaci i vetrovi mogu produžiti sezonu, a druge je skratiti. Dugoročni trend i pojedinačna godina nisu isto.']},
        {h:'Zašto je ranije topljenje raslo tako brzo?',p:['Kada se beli led povuče, otkriva se tamna morska voda. Ona upija više Sunčeve energije nego led, pa se okean dodatno zagreva i na jesen sporije zamrzava. U 2000-im godinama ova povratna sprega snažno je produžavala sezonu. Istraživanje naglašava da je kasnije jesenje smrzavanje bilo važniji deo promene od sve ranijeg prolećnog topljenja.','Posle 2010. drugačiji obrasci oblačnosti u pojedinim oblastima smanjivali su količinu Sunčeve svetlosti koja stiže do mora. To može privremeno oslabiti rast trajanja sezone. Ipak, današnji led je tanji i mlađi od nekadašnjeg višegodišnjeg leda, pa ostaje osetljiv na vremenske promene.']},
        {h:'Kako su istraživači proverili nalaz?',p:['Tim je spojio dug niz satelitskih posmatranja i upoređivao početak topljenja sa trenutkom ponovnog zaleđivanja. Na NASA mapama crveno označava oblasti u kojima se sezona produžavala, a plavo one u kojima se skraćivala. Mapa za 2000-e je pretežno crvena; mapa za kasniji period pokazuje mešovitiji obrazac. Razlika je vidljiva, ali boje ne govore da je led ponovo debeo.','Istraživači su zatim razmatrali energetski bilans: koliko toplote stiže od Sunca, atmosfere i okeana, a koliko je Zemlja vraća u svemir. Takva provera je važna jer ista promena trajanja sezone može imati različite uzroke. Merenja ne mogu unapred reći hoće li zastoj potrajati.']},
        {h:'Šta ovaj rezultat ne znači?',p:['Arktik se i dalje zagreva znatno brže od globalnog proseka, a preostali morski led je tanji nego pre više decenija. Sezona topljenja je u celini mnogo duža nego 1979. Kratak zastoj u njenom daljem produžavanju zato ne poništava gubitak leda i ne dokazuje da su klimatske promene prestale.','Naučnici upozoravaju da se obrazac može ponovo promeniti, posebno ako nastavi da se stanjuje preostali deblji led severno od Grenlanda i kanadskog Arktičkog arhipelaga. Nastavak satelitskih merenja pomoći će da razlikujemo prolaznu pauzu od trajnije promene.']}]},
      sl:{slug:'sezona-taljenja-arkticnega-ledu-upocasnila-rast',title:'Zakaj se sezona taljenja arktičnega ledu ne podaljšuje več tako hitro?',lead:'Sateliti po letu 2010 kažejo zastoj enega trenda, vendar je arktični led še vedno veliko bolj ogrožen kot pred desetletji.',take:['Sezona taljenja je približno 40 dni daljša kot leta 1979.','Po približno letu 2010 se njena povprečna dolžina ni več bistveno spreminjala.','To ne pomeni, da se je segrevanje Arktike ustavilo.'],term:'Sezona taljenja — čas med začetkom spomladanskega taljenja morskega ledu in ponovnim jesenskim zmrzovanjem.',sections:[
        {h:'Kaj so sateliti opazili?',p:['Od leta 1979 raziskovalci spremljajo, kdaj se arktični morski led začne taliti in kdaj znova zamrzne. Nova analiza podatkov do leta 2023 kaže, da je sezona taljenja danes približno 40 dni daljša kot na začetku meritev. Največ se je podaljšala pred letom 2010; pozneje povprečna dolžina ni več rasla z enako hitrostjo.','Rezultat je zanimiv, ker se arktični zrak še naprej hitro segreva. Znanstveniki zato ne govorijo o okrevanju ledu, temveč o spremenjenem prepletanju vplivov. Nevihte, oblaki in veter lahko eno leto sezono podaljšajo, naslednje pa skrajšajo. Posamezno leto ni isto kot dolgoročni trend.']},
        {h:'Zakaj je prej sezona rasla tako hitro?',p:['Ko se bel led umakne, se razkrije temna morska voda. Ta vpije več Sončeve energije, zato se ocean dodatno ogreje in jeseni počasneje zamrzne. V 2000-ih je ta povratna zanka močno podaljševala sezono. Raziskava poudarja, da je bilo poznejše jesensko zmrzovanje pomembnejše od zgodnejšega spomladanskega taljenja.','Po letu 2010 so drugačni vzorci oblačnosti ponekod zmanjšali količino sončne svetlobe, ki doseže morje. To lahko začasno oslabi rast dolžine sezone. Toda današnji led je tanjši in mlajši od nekdanjega večletnega ledu, zato je še posebej občutljiv na spremembe vremena.']},
        {h:'Kako so preverili ugotovitev?',p:['Ekipa je povezala dolgo vrsto satelitskih opazovanj in primerjala začetek taljenja s ponovnim zmrzovanjem. Na Nasinih zemljevidih rdeča kaže območja, kjer se je sezona daljšala, modra pa tista, kjer se je krajšala. Zemljevid za 2000-a je večinoma rdeč, poznejši pa bolj pisan. Barve kažejo spremembo trenda, ne vrnitve debelega ledu.','Raziskovalci so preučili še energijsko bilanco: koliko toplote prispe od Sonca, ozračja in oceana ter koliko je Zemlja odda v vesolje. Takšna primerjava je pomembna, ker ima lahko enaka sprememba dolžine sezone različne vzroke. Meritve ne povedo, ali bo zastoj trajal.']},
        {h:'Česa rezultat ne pomeni?',p:['Arktika se še vedno segreva precej hitreje od svetovnega povprečja, preostali led pa je tanjši kot pred desetletji. Sezona taljenja je v celoti veliko daljša kot leta 1979. Kratek zastoj njenega nadaljnjega podaljševanja ne izniči izgube ledu in ne pomeni konca podnebnih sprememb.','Znanstveniki opozarjajo, da se lahko vzorec spet spremeni, zlasti če se še naprej tanjša debelejši led severno od Grenlandije in kanadskega Arktičnega arhipelaga. Nadaljnje satelitske meritve bodo pokazale, ali gre za prehodno premor ali trajnejšo spremembo.']}]},
      en:{slug:'why-arctic-melt-season-stopped-lengthening-as-fast',title:'Why has the Arctic melt season stopped growing as quickly?',lead:'Satellites show a pause in one trend since about 2010, but Arctic sea ice remains far more vulnerable than it was decades ago.',take:['The melt season is roughly 40 days longer than in 1979.','Its average length has changed little since about 2010.','That does not mean Arctic warming has stopped.'],term:'Melt season — the time between the start of spring sea-ice melt and autumn refreezing.',sections:[
        {h:'What did satellites actually see?',p:['Researchers have tracked when Arctic sea ice begins to melt and refreezes since 1979. A new analysis through 2023 finds that the season is now about 40 days longer than at the start of the record. Most of that increase happened before 2010. Since then, the average length has not kept rising at the same pace.','That is surprising because Arctic air continues to warm rapidly. Scientists are not calling it an ice recovery. Instead, the balance between influences has shifted. Storms, clouds and winds can lengthen the season in one year and shorten it in another. A single year and a long-term trend answer different questions.']},
        {h:'Why did the season grow so quickly before?',p:['When bright ice retreats, it exposes darker seawater. The water absorbs more sunlight, warms and takes longer to freeze in autumn. This feedback strongly lengthened melt seasons during the 2000s. The study finds that later autumn freeze-up contributed more to the long-term change than progressively earlier spring melt.','After 2010, different cloud patterns reduced the sunlight reaching parts of the Arctic Ocean. That can temporarily weaken the increase in season length. Yet today’s ice is thinner and younger than the multiyear ice that once dominated. It remains sensitive to year-to-year weather.']},
        {h:'How was the finding checked?',p:['The team assembled a long series of satellite observations and compared melt onset with refreezing. On NASA’s maps, red marks places where the season grew longer and blue where it shortened. The map for the 2000s is mostly red; the later map is more mixed. This contrast shows a change in the rate of growth, not a return of thick ice.','Researchers also examined the Arctic energy balance: heat arriving from the Sun, atmosphere and ocean, and heat leaving for space. That matters because similar changes in season length can have different causes. The measurements cannot yet tell us whether the pause will last.']},
        {h:'What does the result not mean?',p:['The Arctic is still warming much faster than the global average, and its remaining sea ice is thinner than it was decades ago. Overall, the melt season remains far longer than in 1979. A pause in further lengthening does not reverse ice loss or show that climate change has ended.','Scientists warn that the pattern could shift again, especially if thicker ice north of Greenland and the Canadian Arctic Archipelago continues to thin. Continued satellite monitoring will help distinguish a temporary pause from a more persistent change.']}]}}
    ,['klima','led']),

  N('polar-ice-loss','ecology','2026-09-16','glacier-loss',
    [['European Space Agency','https://www.esa.int/Applications/Observing_the_Earth/FutureEO/Faster-flowing_glaciers_fuel_decades_of_polar_ice_loss']],
    {credit:'Modified Copernicus Sentinel data (2026), processed by ESA',source:'https://www.esa.int/ESA_Multimedia/Images/2026/09/Thwaits_Glacier_Antarctica',license:esaLicence,
      alt:{sr:'Satelitski snimak glečera Tvejts na Antarktiku.',sl:'Satelitski posnetek ledenika Thwaites na Antarktiki.',en:'Satellite image of Thwaites Glacier in Antarctica.'},
      caption:{sr:'Glečer Tvejts snimljen 2026; snimak ilustruje proces, ali je mlađi od perioda obuhvaćenog istraživanjem.',sl:'Ledenik Thwaites leta 2026; posnetek je ilustracija in je mlajši od obdobja raziskave.',en:'Thwaites Glacier in 2026; this illustrative image postdates the study period.'}},
    {
      sr:{slug:'gleceri-ubrzali-gubitak-polarnog-leda',title:'Glečeri ubrzali gubitak leda na Grenlandu i Antarktiku',lead:'Analiza pola veka satelitskih podataka pokazuje da su ledeni pokrivači izgubili oko 11,3 biliona tona leda. Većina je otišla u okean bržim kretanjem glečera.',take:['Dva ledena pokrivača izgubila su oko 11,3 biliona tona leda od 1979. do 2023.','Oko 84% ukupnog gubitka povezano je sa oticanjem leda u more.','Taj gubitak je podigao globalni nivo mora za oko 3,14 cm.'],term:'Bilans mase leda — razlika između novog snega koji se zadržava na ledenom pokrivaču i leda koji on izgubi.',sections:[
        {h:'Šta pokazuje najduži niz podataka?',p:['Međunarodni tim IMBIE sastavio je dosad najduži uporediv niz promena ledenih pokrivača Grenlanda i Antarktika. Od 1979. do 2023. oni su zajedno izgubili oko 11,3 biliona tona leda. Ta voda je doprinela globalnom porastu nivoa mora za približno 3,14 centimetara. Broj deluje mali dok ga ne pomnožimo ogromnom površinom svih okeana.','Grenland je u tom porastu učestvovao sa oko 1,81 centimetar, a Antarktik sa 1,33 centimetra. Važno je razlikovati godišnje oscilacije od višedecenijskog trenda. Poslednjih nekoliko godina gubitak je privremeno sporije rastao, ali ukupni bilans oba ledena pokrivača ostao je negativan.']},
        {h:'Led ne nestaje samo topljenjem na površini',p:['Kada zamislimo gubitak leda, često pomislimo na lokve nastale na površini. Međutim, studija procenjuje da je oko 84 odsto ukupnog gubitka nastalo tako što su se glečeri brže kretali i iznosili led u more. Preostali deo odnosi se na površinsko topljenje. U zapadnoj Antarktici posebno se prate glečeri Pine Island i Tvejts.','Morska voda može zagrevati donju stranu plivajućih ledenih delova. Kada njihova potpora oslabi, led iz unutrašnjosti može lakše da se kreće ka obali. Zato se stanje ledenog pokrivača ne može razumeti samo merenjem letnje temperature vazduha ili gledanjem jedne fotografije obale.']},
        {h:'Kako se mere trilioni tona?',p:['Nijedan satelit ne vidi sve. Jedni mere visinu površine, drugi promene gravitacije, a radar i optičke kamere prate kretanje glečera. IMBIE je uskladio 42 nezavisna istraživanja zasnovana na podacima 27 satelitskih misija. Time se razlike između instrumenata odvajaju od stvarnih promena leda.','Za Grenland niz seže do 1972, a za Antarktik do 1979. Takvi dugi zapisi su dragoceni jer nekoliko snežnih zima ili hladnijih leta može zakloniti trajni gubitak. Satelitski snimak Tvejtsa uz ovaj tekst nastao je 2026, dakle posle perioda studije, i služi kao ilustracija glečera, ne kao samostalan dokaz izračunatog gubitka.']},
        {h:'Zašto su centimetri važni?',p:['Podizanje mora povećava opasnost od poplava i erozije, naročito kada se visoka plima spoji sa olujom. Autori procenjuju da samo nešto više od tri centimetra mogu povećati broj ugroženih ljudi za više miliona. Ta procena zavisi od mesta, obalne zaštite i drugih promena, pa nije prognoza za svaku obalu.','Još važnije, merenja pomažu da se poboljšaju modeli budućeg porasta nivoa mora. Ako znamo kako glečeri reaguju na topliji okean, možemo bolje razumeti šta bi moglo uslediti. Kratko usporavanje ne briše decenije ubrzanog gubitka leda.']}]},
      sl:{slug:'ledeniki-pospesili-izgubo-polarnega-ledu',title:'Ledeniki pospešujejo izgubo ledu na Grenlandiji in Antarktiki',lead:'Analiza pol stoletja satelitskih podatkov kaže izgubo približno 11,3 bilijona ton ledu. Večino so hitreje tekoči ledeniki odnesli v ocean.',take:['Ledeni plošči sta med letoma 1979 in 2023 izgubili približno 11,3 bilijona ton ledu.','Okoli 84 % izgube je povezane z odtekanjem ledu v morje.','Izguba je globalno morsko gladino dvignila za približno 3,14 cm.'],term:'Masna bilanca ledu — razlika med novim snegom, ki ostane na ledeni plošči, in ledom, ki ga plošča izgubi.',sections:[
        {h:'Kaj kaže najdaljši niz podatkov?',p:['Mednarodna skupina IMBIE je sestavila doslej najdaljši primerljiv niz sprememb ledenih plošč Grenlandije in Antarktike. Med letoma 1979 in 2023 sta skupaj izgubili približno 11,3 bilijona ton ledu. Voda je prispevala približno 3,14 centimetra k globalnemu dvigu morske gladine. Število se zdi majhno, dokler ga ne povežemo z ogromno površino oceanov.','Grenlandija je prispevala približno 1,81 centimetra, Antarktika pa 1,33 centimetra. Ločiti moramo letna nihanja od večdesetletnega trenda. V zadnjih nekaj letih je bila izguba začasno počasnejša, vendar je bila skupna masna bilanca obeh plošč še vedno negativna.']},
        {h:'Led ne izginja le s površinskim taljenjem',p:['Ob izgubi ledu si pogosto predstavljamo luže na površini. Toda študija ocenjuje, da je okoli 84 odstotkov skupne izgube nastalo, ker so ledeniki tekli hitreje in nosili led v morje. Preostanek je povezan s površinskim taljenjem. Na zahodu Antarktike posebej spremljajo ledenika Pine Island in Thwaites.','Morska voda lahko segreva spodnjo stran plavajočega ledu. Ko ta opora oslabi, led iz notranjosti laže teče proti obali. Zato stanja ledene plošče ne moremo razumeti zgolj iz poletne temperature zraka ali ene fotografije obale.']},
        {h:'Kako izmerimo bilijone ton?',p:['Noben satelit ne vidi vsega. Nekateri merijo višino površja, drugi spremembe težnosti, radar in optične kamere pa gibanje ledenikov. IMBIE je uskladil 42 neodvisnih raziskav s podatki 27 satelitskih misij. Tako je mogoče razlike med instrumenti ločiti od resničnih sprememb ledu.','Za Grenlandijo zapis sega do leta 1972, za Antarktiko do 1979. Dolgi nizi so pomembni, ker lahko nekaj snežnih zim ali hladnejših poletij zakrije trajno izgubo. Satelitska slika Thwaitesa ob besedilu je iz leta 2026, torej po obdobju študije; ledenik ponazarja, ni pa sama dokaz izračunane izgube.']},
        {h:'Zakaj so centimetri pomembni?',p:['Višja morska gladina poveča nevarnost poplav in erozije, še posebej ob plimi in nevihti. Avtorji ocenjujejo, da lahko nekaj več kot trije centimetri povečajo število ogroženih ljudi za več milijonov. Učinek je odvisen od kraja, zaščite obale in drugih sprememb, zato to ni napoved za vsako obalo.','Meritve predvsem izboljšujejo modele prihodnjega dviga morja. Če vemo, kako ledeniki reagirajo na toplejši ocean, lahko bolje razumemo naslednje spremembe. Kratko upočasnjevanje ne izbriše desetletij pospešene izgube ledu.']}]},
      en:{slug:'faster-glaciers-drive-polar-ice-loss',title:'Faster glaciers drive decades of polar ice loss',lead:'A half-century satellite record shows that Greenland and Antarctica lost about 11.3 trillion tonnes of ice. Faster glacier flow carried most of it into the sea.',take:['The two ice sheets lost about 11.3 trillion tonnes from 1979 to 2023.','About 84% of the loss came from ice flowing into the ocean.','That loss raised global sea level by about 3.14 cm.'],term:'Ice-sheet mass balance — the difference between snow that stays on an ice sheet and ice that leaves it.',sections:[
        {h:'What does the longest record show?',p:['The international IMBIE team assembled the longest comparable record yet of change in the Greenland and Antarctic ice sheets. Together they lost about 11.3 trillion tonnes of ice between 1979 and 2023. That water contributed roughly 3.14 centimetres to global sea-level rise. The figure sounds small until it is spread across the immense area of the oceans.','Greenland contributed around 1.81 centimetres and Antarctica 1.33 centimetres. Annual swings must be separated from a decades-long trend. Loss slowed temporarily in some recent years, but the overall mass balance of both ice sheets remained negative.']},
        {h:'Ice does not disappear only through surface melting',p:['It is easy to picture puddles on the ice surface. Yet the study estimates that about 84 per cent of the total loss occurred as glaciers sped up and discharged more ice into the sea. Surface melting accounts for the rest. Pine Island and Thwaites Glaciers in West Antarctica are watched especially closely.','Ocean water can warm the underside of floating ice. If that supporting ice weakens, ice inland may flow toward the coast more easily. Summer air temperature or a single coastal photograph therefore cannot tell the whole story of an ice sheet.']},
        {h:'How do we measure trillions of tonnes?',p:['No satellite measures everything. Some instruments track surface height, others changes in gravity, while radar and optical sensors follow glacier motion. IMBIE reconciled 42 independent surveys drawing on 27 satellite missions. That helps separate differences between instruments from real changes in ice.','The Greenland record reaches back to 1972 and the Antarctic record to 1979. Long series matter because a few snowy winters or cooler summers can hide persistent loss. The accompanying 2026 image of Thwaites was taken after the study period: it illustrates a glacier but is not, by itself, evidence for the calculated loss.']},
        {h:'Why do a few centimetres matter?',p:['Rising seas increase flood and erosion risks, especially when high tides combine with storms. The researchers estimate that just over three centimetres may put millions more people at risk. The effect depends on location, coastal defences and other changes, so this is not a forecast for every shoreline.','Most importantly, the measurements improve models of future sea-level rise. Understanding how glaciers respond to warmer oceans helps us judge what might come next. A short-term slowdown does not erase decades of accelerating ice loss.']}]}}
    ,['klima','led','sateliti']),
  N('lunar-ai-model','technology','2026-09-10','lunar-ai',
    [['NASA Science','https://science.nasa.gov/science-research/artificial-intelligence-lunar-foundation-model/']],
    {credit:'NASA/GSFC/Arizona State University',source:'https://science.nasa.gov/science-research/artificial-intelligence-lunar-foundation-model/',license:nasaMedia,
      alt:{sr:'Detaljan satelitski snimak kratera na površini Meseca.',sl:'Podroben satelitski posnetek kraterjev na površju Lune.',en:'Detailed orbital image of craters on the Moon.'},
      caption:{sr:'Snimci Mesečeve površine služe kao podaci za novi model; prikaz nije dokaz pronalaska vode.',sl:'Posnetki Luninega površja so podatki za novi model; slika ni dokaz odkritja vode.',en:'Lunar surface images feed the new model; this picture is not evidence of a water discovery.'}},
    {
      sr:{slug:'nasa-i-ibm-napravili-ai-model-za-proucavanje-meseca',title:'NASA i IBM napravili AI model za proučavanje Meseca',lead:'Novi otvoreni model uči iz oko dva miliona isečaka snimaka Mesečeve površine. Može pomoći istraživačima da brže pronađu zanimljive oblike terena, ali nalaze moraju proveriti ljudi.',take:['Model je treniran na približno dva miliona isečaka snimaka.','Uči obrasce sa slika, a ne fizičke zakone Meseca.','Predložena mesta za istraživanje zahtevaju nezavisnu proveru.'],term:'Osnovni AI model — sistem prethodno obučen na velikoj zbirci podataka, koji se zatim prilagođava konkretnim zadacima.',sections:[
        {h:'Šta je zapravo predstavljeno?',p:['NASA i IBM objavili su osnovni model veštačke inteligencije za lunarnu nauku. Umesto da za svaki zadatak uči od početka, model najpre traži pravilnosti u velikoj zbirci orbitalnih slika. Istraživači ga zatim mogu prilagoditi prepoznavanju kratera, vulkanskih oblika ili terena koji zaslužuje detaljnije ispitivanje. Model i prateći alati otvoreno su dostupni naučnoj zajednici.','Za obuku je upotrebljeno približno dva miliona isečaka slika sa letelice Lunar Reconnaissance Orbiter. Podaci uključuju vrlo detaljne snimke, na kojima jedan piksel predstavlja oko metar tla, kao i višespektralne prikaze grublje rezolucije. Različite skale daju različite informacije: mala stena i čitav region ne mogu se proučavati na isti način.']},
        {h:'Kako računar može pomoći istraživanju?',p:['Mesec je pokriven kraterima i slojevima nastalim tokom milijardi godina. Ljudi mogu pažljivo da analiziraju mali broj slika, ali milioni kadrova traže mnogo vremena. Model može da predloži slična područja, označi neobične oblike i pomogne da se napravi doslednija karta. Naučnik zatim proverava označeno područje i poredi ga sa drugim podacima.','Jedna moguća primena je izbor lokacija blizu Mesečevih polova, gde trajna senka može čuvati led. Sama tamna slika, međutim, ne dokazuje da vode ima. Za takav zaključak potrebno je uporediti temperaturu, osvetljenje, spektre i, na kraju, uzorke ili neposredna merenja. AI je zato pomoć pri postavljanju pitanja, a ne zamena za eksperiment.']},
        {h:'Zašto je ovo važnije od jedne pametne pretrage?',p:['Isti prethodno obučeni sistem mogao bi da posluži za više različitih zadataka. Manji istraživački timovi tako ne moraju svaki put da prikupljaju ogromnu zbirku označenih primera. Otvoren pristup omogućava drugima da ponove postupak, testiraju ga na novim predelima i prijave greške. To je posebno korisno kada se planiraju buduće misije, jer vreme i instrumenti na letelici imaju ograničenja.','Model može pogrešiti kada naiđe na teren koji se razlikuje od njegovih podataka za obuku. Senke, ugao Sunčeve svetlosti i kvalitet snimka mogu navesti algoritam da vidi obrazac koji nije stvaran. Zato se procenjuju i tačnost i nesigurnost, a najzanimljiviji nalazi proveravaju nezavisnim instrumentima. Objava modela nije objava novog otkrića na Mesecu.']},
        {h:'Šta sledi?',p:['Istraživači sada mogu da ispitaju koliko dobro model radi u mapiranju konkretnih oblika i da ga prilagode svojim pitanjima. Njegova vrednost zavisi od toga da li štedi vreme, smanjuje greške i daje proverljive rezultate. Najkorisniji ishod bio bi bolje usmeravanje teleskopa, orbitalnih kamera i budućih roverâ ka mestima gde se zaista može naučiti nešto novo.']}]},
      sl:{slug:'nasa-in-ibm-sta-ustvarila-model-ai-za-luno',title:'NASA in IBM sta ustvarila model AI za raziskovanje Lune',lead:'Novi odprti model se uči iz približno dveh milijonov izrezov posnetkov Luninega površja. Raziskovalcem lahko pomaga hitreje najti zanimiv teren, vendar morajo ugotovitve preveriti ljudje.',take:['Model so učili na približno dveh milijonih izrezov slik.','Prepoznava vzorce na posnetkih, ne fizikalnih zakonov Lune.','Predlagane lokacije zahtevajo neodvisno preverjanje.'],term:'Temeljni model AI — sistem, najprej naučen na veliki zbirki podatkov, ki ga nato prilagodimo posameznim nalogam.',sections:[
        {h:'Kaj so predstavili?',p:['NASA in IBM sta objavila temeljni model umetne inteligence za lunarno znanost. Namesto učenja od začetka za vsako nalogo model najprej išče pravilnosti v velikem naboru orbitalnih slik. Raziskovalci ga lahko nato prilagodijo prepoznavanju kraterjev, vulkanskih oblik ali območij, vrednih natančnejšega pregleda. Model in orodja so odprto dostopni raziskovalni skupnosti.','Za učenje so uporabili približno dva milijona izrezov posnetkov sonde Lunar Reconnaissance Orbiter. Vključujejo zelo podrobne slike, na katerih piksel pomeni približno meter tal, ter večspektralne posnetke z manjšo ločljivostjo. Različna merila razkrijejo različne značilnosti: majhne skale in cele pokrajine ne proučujemo enako.']},
        {h:'Kako lahko računalnik pomaga?',p:['Luno prekrivajo kraterji in plasti iz več milijard let. Človek lahko skrbno pregleda manjše število slik, milijoni posnetkov pa zahtevajo veliko časa. Model lahko predlaga podobna območja, označi nenavadne oblike in pomaga izdelati doslednejši zemljevid. Znanstvenik nato predlog preveri z drugimi podatki.','Možna uporaba je izbira območij blizu Luninih polov, kjer bi večna senca lahko ohranila led. Temna slika sama po sebi še ne dokazuje vode. Primerjati je treba temperaturo, osvetlitev, spektre in nazadnje tudi vzorce ali neposredne meritve. AI pomaga oblikovati vprašanja; ni nadomestilo za poskus.']},
        {h:'Zakaj več kot le pametno iskanje?',p:['Isti predhodno naučeni sistem lahko služi različnim nalogam. Manjšim raziskovalnim skupinam tako ni treba vsakič zbrati ogromnega nabora označenih primerov. Odprti dostop drugim omogoča ponavljanje postopka, preverjanje na novih območjih in odkrivanje napak. To je koristno pri načrtovanju misij, kjer so čas in zmogljivosti instrumentov omejeni.','Model se lahko zmoti na terenu, ki se razlikuje od učnih podatkov. Sence, kot Sonca in kakovost posnetka lahko povzročijo lažen vzorec. Zato je treba oceniti točnost in negotovost ter najbolj zanimive predloge preveriti z neodvisnimi instrumenti. Objava modela sama ni objava novega odkritja na Luni.']},
        {h:'Kaj sledi?',p:['Raziskovalci lahko zdaj preizkusijo model pri konkretnih kartografskih nalogah in ga prilagodijo svojim vprašanjem. Koristen bo, če prihrani čas, zmanjša napake in daje preverljive rezultate. Najboljša uporaba je usmerjanje teleskopov, orbitalnih kamer in prihodnjih roverjev na kraje, kjer lahko res izvemo kaj novega.']}]},
      en:{slug:'nasa-ibm-open-ai-model-for-moon-science',title:'NASA and IBM release an AI model for Moon science',lead:'The open model learned from roughly two million lunar image patches. It may help researchers find interesting terrain faster, but people must verify its suggestions.',take:['The model trained on about two million image patches.','It learns patterns in pictures, not the laws of lunar physics.','Suggested sites still need independent verification.'],term:'Foundation AI model — a system pretrained on a large dataset and then adapted to particular tasks.',sections:[
        {h:'What was actually released?',p:['NASA and IBM have released a foundation model for lunar science. Rather than learning every task from scratch, it first looks for patterns across a large collection of orbital images. Researchers can then adapt it to find craters, volcanic features or terrain worth a closer look. The model and its tools are openly available for others to test.','Training used about two million image patches from the Lunar Reconnaissance Orbiter. The material includes detailed views with roughly one metre per pixel and coarser multispectral images. The scales answer different questions: a small boulder and a whole geological province cannot be studied in the same way.']},
        {h:'How could a computer help?',p:['Craters and geological layers cover the Moon after billions of years of impacts and eruptions. People can inspect a selection of pictures carefully, but millions of frames take enormous time. A model can flag similar regions, mark unusual shapes and help create consistent maps. A scientist must then check each promising region against other evidence.','One possible use is choosing sites near the lunar poles, where permanent shadow might preserve ice. A dark image alone does not prove water is present. Temperature, illumination, spectra and eventually samples or direct measurements are needed. AI helps ask better questions; it does not replace an experiment.']},
        {h:'Why is this more than a clever search?',p:['The same pretrained system could be adapted to several tasks. Small research teams would not have to assemble a vast labelled training set each time. Open access lets other scientists repeat the process, test unfamiliar terrain and report mistakes. This matters when planning missions because spacecraft time and instrument capacity are limited.','The model may fail on terrain unlike its training images. Shadows, changing sunlight and image quality can make an algorithm detect a pattern that is not there. Accuracy and uncertainty therefore need testing, and exciting candidates require independent instruments. Releasing the model is not the same as announcing a new lunar discovery.']},
        {h:'What happens next?',p:['Researchers can now test it on specific mapping questions and refine it for their own work. Its value will depend on whether it saves time, reduces mistakes and produces results that others can check. A practical outcome would be directing cameras and future rovers toward places where they are most likely to learn something new.']}]}},
    ['Mesec','AI','sateliti']),

  N('earth-center-of-mass','physics','2026-09-16','earth-center',
    [['NASA','https://www.nasa.gov/science-research/earth-science/nasa-watches-earths-weight-finds-center-of-mass/']],
    {credit:'NASA Scientific Visualization Studio',source:'https://www.nasa.gov/science-research/earth-science/nasa-watches-earths-weight-finds-center-of-mass/',license:nasaMedia,
      alt:{sr:'Ilustracija Zemlje i merenja položaja njenog centra mase.',sl:'Ilustracija Zemlje in merjenja lege njenega masnega središča.',en:'Illustration of Earth and measurements of its center of mass.'},
      caption:{sr:'Zemljin centar mase određuje se kombinovanjem različitih svemirskih i zemaljskih merenja.',sl:'Masno središče Zemlje določajo s povezovanjem vesoljskih in zemeljskih meritev.',en:'Earth’s center of mass is found by combining measurements from space and the ground.'}},
    {
      sr:{slug:'kako-nasa-prati-pomeranje-centra-zemlje',title:'Kako NASA prati pomeranje centra Zemlje za svega nekoliko milimetara',lead:'Voda, sneg i led menjaju raspored mase naše planete. Izuzetno precizna merenja pokazuju da se zato i njeno težište neznatno pomera tokom godine.',take:['Centar mase Zemlje pomera se za nekoliko milimetara kroz godišnja doba.','Naučnici kombinuju laser, satelite i stanična merenja.','Precizan zajednički koordinatni sistem važan je za navigaciju i klimu.'],term:'Geocentar — centar mase cele Zemlje, uključujući njene okeane, atmosferu i led.',sections:[
        {h:'Kako centar planete može da se pomera?',p:['Zamislimo loptu u kojoj se voda polako premešta s jedne strane na drugu. Sama lopta ne mora da se pomeri, ali njeno težište hoće. Slično tome, sneg se tokom zime taloži na kontinentima, u proleće se topi, a reke prenose vodu u okeane. Promene su ogromne po količini materijala, ali je Zemlja još mnogo masivnija, pa se njen centar mase pomera samo za milimetre.','NASA navodi primere sezonskog pomeranja: oko tri milimetra prema severu kada se u martu nakupi sneg na severnoj hemisferi, i oko 2,2 milimetra prema jugu kada u aprilu voda obilno ispuni sliv Amazona. To nisu putovanja planete kroz svemir, već promene referentne tačke unutar Zemljinog sistema.']},
        {h:'Kako se meri nešto toliko malo?',p:['Naučnici laserskim impulsima mere rastojanje do satelita LAGEOS. Satelit nosi reflektore koji vraćaju svetlost ka stanici na tlu; iz vremena povratka dobija se vrlo precizno rastojanje. U analizu ulaze i navigacioni sateliti, drugi sateliti u niskoj orbiti i stanice koje prate deformaciju Zemljine kore. Nema jednog uređaja koji samostalno daje odgovor.','Poseban izazov je što se i posmatračke stanice pomeraju zbog tektonike, plime i promena opterećenja. Merenja moraju da razdvoje kretanje stanice od promene samog geocentra. Kada se nezavisne metode slože, naučnici dobijaju pouzdaniji koordinatni okvir za planetu.']},
        {h:'Zašto je važna referentna tačka?',p:['GPS ili naučni satelit ne može imati tačan položaj bez dogovora o tome gde je početak koordinatnog sistema. Pogrešno postavljen centar od nekoliko milimetara može izgledati zanemarljivo, ali postaje bitan kada se porede višedecenijska merenja nivoa mora, visine ledenih pokrivača ili pomeranja tla. Različiti sateliti moraju govoriti istim „jezikom” položaja.','Ova merenja pomažu i da se prati kako se voda premešta među okeanom, kopnom, atmosferom i ledom. Time precizna geodezija postaje alat za razumevanje hidrološkog ciklusa i klimatskih promena. Ona sama ne govori zašto se klima menja; pruža pouzdanu osnovu za poređenje drugih podataka.']},
        {h:'Šta nam to govori o nauci?',p:['Priča pokazuje kako sitno pomeranje može otkriti velike procese. Naučnici ne gledaju neposredno u centar Zemlje; oni kombinuju mnogo merenja, računaju moguća objašnjenja i proveravaju da li se rezultati poklapaju. Što su instrumenti precizniji, to je važnije razumeti i njihove greške.']}]},
      sl:{slug:'kako-nasa-meri-premikanje-sredisca-zemlje',title:'Kako NASA meri nekajmilimetrsko premikanje središča Zemlje',lead:'Voda, sneg in led spreminjajo razporeditev mase planeta. Zelo natančne meritve zato pokažejo drobno sezonsko premikanje težišča.',take:['Masno središče Zemlje se sezonsko premakne za nekaj milimetrov.','Znanstveniki združujejo laserje, satelite in talne postaje.','Natančen skupni koordinatni sistem je pomemben za navigacijo in spremljanje podnebja.'],term:'Geocenter — masno središče celotne Zemlje skupaj z oceani, ozračjem in ledom.',sections:[
        {h:'Kako se lahko središče planeta premika?',p:['Predstavljajmo si kroglo, v kateri voda počasi teče z ene strani na drugo. Krogla lahko miruje, njeno težišče pa se premakne. Podobno se sneg pozimi kopiči na celinah, spomladi tali, reke pa nosijo vodo v oceane. Premikajo se ogromne količine snovi, vendar je Zemlja še veliko masivnejša, zato se masno središče premakne le za milimetre.','NASA navaja sezonska primera: marca približno tri milimetre proti severu zaradi snega na severni polobli in aprila približno 2,2 milimetra proti jugu, ko je porečje Amazonke polno vode. To ni potovanje planeta po vesolju, temveč sprememba referenčne točke v Zemljinem sistemu.']},
        {h:'Kako izmerimo tako majhno spremembo?',p:['Laserski žarki merijo razdaljo do satelitov LAGEOS. Njihovi odbojniki vrnejo svetlobo na talno postajo; iz časa povratka izračunamo razdaljo. Znanstveniki uporabljajo tudi navigacijske satelite, druga plovila v nizki orbiti in postaje, ki merijo deformacije Zemljine skorje. Nobena naprava sama ne poda celotnega odgovora.','Zaplet je, da se opazovalne postaje premikajo zaradi tektonike, plimovanja in sprememb obremenitve. Analiza mora ločiti gibanje postaje od premika geocentra. Ujemanje neodvisnih metod daje zanesljivejši planetarni koordinatni okvir.']},
        {h:'Zakaj je referenčna točka pomembna?',p:['GPS ali znanstveni satelit ne more imeti točnega položaja brez dogovora o izhodišču koordinat. Napaka nekaj milimetrov se zdi majhna, a je pomembna pri primerjavi večdesetletnih meritev morske gladine, višine ledu ali premikov tal. Različni sateliti morajo uporabljati isto prostorsko osnovo.','Meritve pomagajo spremljati prehajanje vode med oceani, kopnim, ozračjem in ledom. Zato je natančna geodezija orodje za razumevanje vodnega kroga in podnebnih sprememb. Sama ne pove, zakaj se podnebje spreminja, omogoča pa zanesljivo primerjavo drugih podatkov.']},
        {h:'Kaj pove o znanstveni metodi?',p:['Drobna sprememba razkrije velike procese. Znanstveniki ne pogledajo neposredno v središče Zemlje; združijo več vrst meritev, izračunajo možne razlage in preverijo, ali se rezultati ujemajo. Bolj ko so instrumenti natančni, pomembnejše je razumeti tudi njihove napake.']}]},
      en:{slug:'how-nasa-measures-earth-shifting-center',title:'How NASA measures Earth’s shifting center to the millimeter',lead:'Water, snow and ice change how our planet’s mass is distributed. Precise measurements reveal a tiny seasonal shift in its center of mass.',take:['Earth’s center of mass moves a few millimeters with the seasons.','Scientists combine lasers, satellites and ground stations.','A precise shared coordinate system supports navigation and climate records.'],term:'Geocenter — the center of mass of the whole Earth system, including oceans, atmosphere and ice.',sections:[
        {h:'How can a planet’s center move?',p:['Imagine a ball with water slowly flowing from one side to the other. The ball might stay in place while its balance point shifts. Likewise, snow piles onto continents during winter, melts in spring and runs through rivers toward the ocean. Enormous amounts of material move, but Earth is vastly more massive, so its center of mass shifts only millimeters.','NASA gives seasonal examples: roughly three millimeters north as Northern Hemisphere snow builds up in March, and about 2.2 millimeters south when water fills the Amazon basin in April. These are changes in a reference point within the Earth system, not the planet traveling through space.']},
        {h:'How can such a small change be measured?',p:['Scientists fire laser pulses toward LAGEOS satellites. Reflectors send the light back to the ground station, and its travel time reveals distance precisely. The analysis also draws on navigation satellites, other low-orbit spacecraft and stations measuring deformation of Earth’s crust. No single instrument provides the complete answer.','The challenge is that observing stations also move with tectonics, tides and changing loads on the surface. Researchers must separate the station’s motion from changes in the geocenter itself. Agreement among independent techniques makes the planetary reference frame more reliable.']},
        {h:'Why care about a reference point?',p:['GPS and scientific satellites need an agreed origin for their coordinates. An error of a few millimeters sounds trivial but matters when comparing decades of sea-level observations, ice-sheet heights or ground motion. Different spacecraft must use the same positional language.','The measurements also help trace water moving among oceans, land, air and ice. Precise geodesy thus helps us understand the water cycle and climate change. It does not, by itself, explain why climate changes; it provides a trustworthy basis for comparing other observations.']},
        {h:'What does this teach us about science?',p:['A tiny shift can reveal large processes. Researchers cannot look directly at Earth’s mass center. They combine several measurements, calculate possible explanations and check whether the answers agree. As instruments become more precise, understanding their errors becomes just as important.']}]}},
    ['Zemlja','merenja','sateliti']),
  N('hypersoft-xray','space','2026-09-09','chandra-xray',
    [['NASA Chandra X-ray Observatory','https://science.nasa.gov/missions/chandra/nasas-chandra-unveils-mysterious-x-ray-objects/']],
    {credit:'X-ray: NASA/CXC/Univ. of Alabama/M. Muhibullah et al.; Optical: NASA/ESA/STScI; processing: NASA/CXC/SAO/N. Wolk',source:'https://science.nasa.gov/missions/chandra/nasas-chandra-unveils-mysterious-x-ray-objects/',license:nasaMedia,
      alt:{sr:'Optički snimak galaksije sa označenim izvorima rendgenskog zračenja.',sl:'Optični posnetek galaksije z označenimi izvori rentgenskega sevanja.',en:'Optical view of a galaxy with X-ray sources marked.'},
      caption:{sr:'Narandžaste oznake pokazuju položaje nekih veoma mekih rendgenskih izvora; boje su dodate radi prikaza podataka.',sl:'Oranžne oznake kažejo položaj nekaterih zelo mehkih rentgenskih virov; barve ponazarjajo podatke.',en:'Orange overlays mark some very soft X-ray sources; the colors visualize measured data.'}},
    {
      sr:{slug:'candra-pronasla-84-neobicna-rendgenska-izvora',title:'Čandra pronašla 84 neobična izvora rendgenskog zračenja',lead:'U šest galaksija izdvojena je grupa objekata koji snažno zrače meke rendgenske zrake i ultraljubičastu svetlost. Njihova priroda još nije potvrđena.',take:['Tim je izdvojio 84 veoma meka rendgenska izvora u šest galaksija.','Jedno objašnjenje su sistemi zvezde i belog patuljka koji privlači gas.','Nijedan objekat nije potvrđen kao buduća supernova.'],term:'Meki rendgenski zraci — rendgensko zračenje niže energije od takozvanih tvrdih rendgenskih zraka.',sections:[
        {h:'Šta je teleskop otkrio?',p:['Svemirska opservatorija Čandra zabeležila je rendgensko zračenje iz šest obližnjih galaksija. Istraživači su izdvojili 84 izvora koji su neobično sjajni u delu spektra niže rendgenske energije. Zato ih nazivaju „veoma mekim” izvorima. Njihovi položaji upoređeni su i sa ultraljubičastim podacima, kako bi se videlo da li više vrsta svetlosti dolazi iz istog područja.','Na ilustraciji uz vest vidi se obična optička slika galaksije, preko koje su položaji rendgenskih izvora naknadno označeni. Narandžasti krugovi nisu boja objekata koju bi ljudsko oko videlo. Astronomi često kombinuju različite delove elektromagnetnog spektra, jer svaki otkriva drugačiji proces.']},
        {h:'Šta bi objekti mogli da budu?',p:['Jedna mogućnost je dvojni sistem: beli patuljak privlači gas sa obližnje zvezde. Dok se gas sabija i zagreva, može emitovati mnogo zračenja. Beli patuljak je gusto jezgro zvezde koja je potrošila gorivo, a ne mala obična zvezda. Slični sistemi zanimljivi su jer neki mogu biti povezani sa nastankom supernova tipa Ia.','Međutim, signal sam po sebi nije dovoljan da se utvrdi sastav svakog od 84 izvora. Udaljenost, prašina između nas i galaksije i ograničena rezolucija mogu sakriti detalje. Potrebna su dodatna posmatranja, naročito promene sjaja tokom vremena i kvalitetniji spektri.']},
        {h:'Zašto je ultraljubičasta svetlost važna?',p:['Ako su izvori zaista veoma vreli sistemi, uz meke rendgenske zrake mogu proizvoditi i mnogo ultraljubičaste svetlosti. Takva energija može jonizovati gas oko njih: iz atoma izbacuje elektrone i menja način na koji gas svetli. Poređenjem rendgenskih i ultraljubičastih podataka naučnici proveravaju da li se pretpostavljeni fizički model uklapa u opažanja.','To je primer zaključivanja na osnovu više tragova. Rendgenska svetlost govori o energičnim procesima, a ultraljubičasta i optička o njihovom okruženju. Kada se različite vrste podataka slažu, objašnjenje postaje uverljivije. Ipak, slaganje ne znači automatski da je pronađen jedini mogući uzrok.']},
        {h:'Šta ostaje otvoreno?',p:['Istraživanje je napravilo katalog kandidata koji će pomoći astronomima da biraju ciljeve za naredna posmatranja. Tek tada će moći bolje da procene koliko su ovi objekti česti i kakvu ulogu imaju u razvoju galaksija. Veza sa supernovama je zanimljiva hipoteza, ali ova vest ne najavljuje eksploziju ni u jednoj od posmatranih galaksija.']}]},
      sl:{slug:'chandra-odkrila-84-nenavadnih-rentgenskih-virov',title:'Chandra je našla 84 nenavadnih rentgenskih virov',lead:'V šestih galaksijah so izločili skupino objektov z močnim mehkim rentgenskim in ultravijoličnim sevanjem. Njihova narava še ni potrjena.',take:['Ekipa je našla 84 zelo mehkih rentgenskih virov v šestih galaksijah.','Možna razlaga je bela pritlikavka, ki iz spremljevalke privlači plin.','Noben vir ni potrjen kot prihodnja supernova.'],term:'Mehki rentgenski žarki — rentgensko sevanje z manjšo energijo od trdih rentgenskih žarkov.',sections:[
        {h:'Kaj je opazil teleskop?',p:['Vesoljski observatorij Chandra je meril rentgensko sevanje v šestih bližnjih galaksijah. Znanstveniki so izločili 84 virov, nenavadno svetlih v manj energijskem delu rentgenskega spektra. Zato jih imenujejo zelo mehki viri. Njihove lege so primerjali z ultravijoličnimi podatki, da bi ugotovili, ali različne vrste svetlobe prihajajo iz istih območij.','Ob članku je običajna optična slika galaksije z naknadno označenimi rentgenskimi viri. Oranžni krogi niso barve, ki bi jih oko dejansko videlo. Astronomi povezujejo različna območja elektromagnetnega spektra, saj vsako razkriva drug proces.']},
        {h:'Kaj bi ti objekti lahko bili?',p:['Možna razlaga je dvojni sistem, v katerem bela pritlikavka privlači plin z bližnje zvezde. Stisnjen in vroč plin lahko močno seva. Bela pritlikavka je gosto ostalo jedro zvezde po porabi goriva, ne majhna navadna zvezda. Takšni sistemi so zanimivi, ker so nekateri lahko povezani s supernovami tipa Ia.','A sam signal ne zadošča za določitev narave vsakega od 84 virov. Oddaljenost, prah med nami in galaksijo ter omejena ločljivost prikrijejo podrobnosti. Potrebna so nadaljnja opazovanja, predvsem časovne spremembe sijaja in boljši spektri.']},
        {h:'Zakaj je pomembna ultravijolična svetloba?',p:['Zelo vroči sistemi bi lahko poleg mehkih rentgenskih žarkov oddajali veliko ultravijolične svetlobe. Ta energija lahko ionizira okoliški plin: iz atomov izbije elektrone in spremeni njihov sij. S primerjavo rentgenskih in ultravijoličnih meritev skupina preverja, ali domnevni fizikalni model ustreza opazovanjem.','Gre za sklepanje iz več sledi. Rentgenski žarki govorijo o energijskih procesih, ultravijolična in optična svetloba pa o okolici. Ujemanje različnih podatkov razlago okrepi, vendar ne dokazuje, da druge možnosti ne obstajajo.']},
        {h:'Kaj ostaja odprto?',p:['Raziskava je ustvarila katalog kandidatov, ki bo astronomom pomagal izbrati prihodnje tarče. Šele nove meritve bodo bolje pokazale, kako pogosti so takšni viri in kaj pomenijo za razvoj galaksij. Povezava s supernovami je zanimiva hipoteza, toda novica ne napoveduje eksplozije v nobeni od opazovanih galaksij.']}]},
      en:{slug:'chandra-finds-84-unusual-x-ray-sources',title:'Chandra finds 84 unusual X-ray sources',lead:'A survey of six galaxies identified objects bright in soft X-rays and ultraviolet light. What they are remains uncertain.',take:['The team identified 84 very soft X-ray sources across six galaxies.','One possibility is a white dwarf drawing gas from a companion star.','None is confirmed to be a future supernova.'],term:'Soft X-rays — X-ray radiation with lower energy than so-called hard X-rays.',sections:[
        {h:'What did the telescope detect?',p:['The Chandra space observatory measured X-rays from six nearby galaxies. Researchers selected 84 sources unusually bright at the lower-energy end of the X-ray spectrum. They call them hypersoft sources. They compared their positions with ultraviolet observations to see whether several kinds of light come from the same regions.','The accompanying graphic starts with an ordinary optical view of a galaxy and adds the positions of X-ray sources. The orange marks are not colors a person would see through a telescope. Astronomers combine parts of the electromagnetic spectrum because each reveals different physical processes.']},
        {h:'What might the objects be?',p:['One possibility is a binary system where a white dwarf pulls gas from a neighboring star. As the gas gathers and heats, it can radiate strongly. A white dwarf is the dense remnant of a star that exhausted its fuel, not an ordinary small star. Such systems are interesting because some may relate to type Ia supernovae.','The signal alone cannot identify every one of the 84 objects. Distance, dust between us and a galaxy, and limited image resolution can hide details. Further observations are needed, especially changes in brightness over time and clearer spectra.']},
        {h:'Why does ultraviolet light matter?',p:['If the sources are very hot systems, they might emit abundant ultraviolet light as well as soft X-rays. That energy can ionize surrounding gas, knocking electrons off atoms and changing how the gas glows. Comparing X-ray and ultraviolet data tests whether a proposed physical model fits the observations.','This is how scientists reason from several clues. X-rays signal energetic processes, while ultraviolet and visible light tell us about their surroundings. Agreement among data types strengthens an explanation, though it does not prove that no alternative exists.']},
        {h:'What remains unknown?',p:['The survey has produced a catalogue of candidates for future observations. New measurements will help establish how common these sources are and what role they play in galaxies. The possible supernova connection is an intriguing hypothesis, but this news does not predict an explosion in any of the observed galaxies.']}]}},
    ['rendgenski zraci','galaksije','zvezde']),
  N('ancient-quasars','space','2026-07-06','ancient-quasar',
    [['European Space Agency — Euclid','https://www.esa.int/Science_Exploration/Space_Science/Euclid/Euclid_discovers_the_most_ancient_quasar_in_the_Universe']],
    {credit:'ESA (artist’s impression)',source:'https://www.esa.int/ESA_Multimedia/Images/2026/07/Artist_s_concept_of_an_ancient_quasar',license:esaLicence,
      alt:{sr:'Umetnička ilustracija sjajnog kvazara u ranom svemiru.',sl:'Umetniška upodobitev svetlega kvazarja v zgodnjem vesolju.',en:'Artist’s impression of a bright quasar in the early universe.'},
      caption:{sr:'Umetnička ilustracija kvazara; stvarni podaci teleskopa Euklid prikazani su niže u tekstu.',sl:'Umetniška upodobitev kvazarja; dejanski podatki teleskopa Evklid so prikazani niže.',en:'An artist’s impression of a quasar; actual Euclid observations appear below.'},
      inline:'news/quasar-observations.png',inlineCredit:'ESA/Euclid/Euclid Consortium/NASA; image processing: Euclid Science Ground Segment and Antoine Basset (CNES)',inlineSource:'https://www.esa.int/ESA_Multimedia/Images/2026/07/Quasars_discovered_by_Euclid',inlineLicense:esaLicence,
      inlineAlt:{sr:'Kolaž stvarnih snimaka udaljenih kvazara koje je zabeležio Euklid.',sl:'Kolaž resničnih posnetkov oddaljenih kvazarjev teleskopa Evklid.',en:'Collage of actual distant quasars observed by Euclid.'},
      inlineCaption:{sr:'Na snimcima Euklida kvazari izgledaju kao sitne tačke; njihova udaljenost određuje se analizom svetlosti.',sl:'Na Evklidovih posnetkih so kvazarji drobne pike; njihovo oddaljenost določajo z analizo svetlobe.',en:'On Euclid images, quasars look like tiny points; analyzing their light reveals their distance.'}},
    {
      sr:{slug:'euklid-otkrio-veoma-stare-kvazare',title:'Euklid otkrio kvazare iz vremena kada je svemir bio veoma mlad',lead:'Evropski teleskop izdvojio je 31 rani kvazar, uključujući dva iz doba oko 670 miliona godina posle Velikog praska. Njihova svetlost otvara pitanje kako su crne rupe brzo rasle.',take:['Euklid je pronašao 31 rani kvazar.','Dva najudaljenija imaju crveni pomak 7,77 i 7,69.','Vidimo ih kakvi su bili oko 670 miliona godina posle Velikog praska.'],term:'Crveni pomak — rastezanje talasne dužine svetlosti dok se svemir širi; astronomima pomaže da procene koliko je izvor daleko u vremenu i prostoru.',sections:[
        {h:'Šta je Euklid našao?',p:['Svemirski teleskop Euklid, namenjen proučavanju velikih razmera svemira, pronašao je 31 kvazar iz njegovog ranog perioda. Dvanaest ima crveni pomak najmanje sedam, što znači da svetlost do nas stiže iz doba kada je svemir bio star manje od milijardu godina. Dva rekordna izvora imaju crveni pomak 7,77 i 7,69; njih vidimo iz vremena oko 670 miliona godina posle Velikog praska.','Na fotografiji oni nisu veliki vrtlozi iz naučne fantastike, već sitne tačke. Upadljivo je koliko su sjajni uprkos ogromnoj udaljenosti. Umetnička slika na vrhu prikazuje kako bi jedan kvazar mogao izgledati izbliza; kolaž ispod donosi stvarne podatke posmatranja. Ta razlika je važna da ilustraciju ne zamenimo za fotografiju objekta.']},
        {h:'Šta je kvazar?',p:['U središtu mnogih galaksija nalazi se supermasivna crna rupa. Kada gas pada prema njoj, pre ulaska u crnu rupu formira vreli disk i emituje ogromnu količinu svetlosti. Takvo izuzetno sjajno aktivno galaktičko jezgro nazivamo kvazar. Ne vidimo samu crnu rupu, već materiju oko nje.','Kvazari su dragoceni kao svetionici ranog svemira. Njihova svetlost putovala je milijardama godina, pa posmatranje dalekog kvazara istovremeno znači gledanje u prošlost. Crveni pomak govori koliko se prostor u međuvremenu širio. On ne znači da se objekat danas nalazi u istom stanju kao u svetlosti koju primamo.']},
        {h:'Zašto su ovako rani kvazari zagonetka?',p:['Ako je crna rupa već u prvih nekoliko stotina miliona godina postala veoma masivna, od nečega je morala nastati i zatim brzo dobijati materiju. Astronomi razmatraju više mogućnosti: velike početne „klice”, veoma brzo hranjenje gasom ili kombinaciju procesa. Novi uzorak od 31 objekta omogućava da se modeli porede sa većim brojem primera.','Ipak, sama vest ne rešava pitanje nastanka prvih supermasivnih crnih rupa. Da bi se procenile njihove mase i okolina, potrebni su spektroskopski podaci i dodatna posmatranja. Nauka napreduje kada se od neobičnog nalaza pređe na merljive testove različitih objašnjenja.']},
        {h:'Kako je potraga uspela?',p:['Euklid posmatra velika područja neba i prepoznaje kandidate na osnovu načina na koji se njihova svetlost raspoređuje po talasnim dužinama. Zatim se obećavajući objekti proveravaju dodatnim merenjima. Takav spoj široke pretrage i detaljne potvrde može otkriti retke objekte koje uski pogledi teleskopa lako promaše.']}]},
      sl:{slug:'evklid-odkril-kvazarje-iz-zgodnjega-vesolja',title:'Evklid je odkril kvazarje iz zelo mladega vesolja',lead:'Evropski teleskop je našel 31 zgodnjih kvazarjev, tudi dva iz časa približno 670 milijonov let po velikem poku. Njuna svetloba odpira vprašanje hitre rasti črnih lukenj.',take:['Evklid je odkril 31 zgodnjih kvazarjev.','Najbolj oddaljena imata rdeči premik 7,77 in 7,69.','Vidimo ju iz časa približno 670 milijonov let po velikem poku.'],term:'Rdeči premik — raztezanje valovne dolžine svetlobe ob širjenju vesolja; pomaga oceniti oddaljenost izvora v prostoru in času.',sections:[
        {h:'Kaj je našel Evklid?',p:['Vesoljski teleskop Evklid, namenjen raziskovanju velikih razsežnosti vesolja, je našel 31 kvazarjev iz zgodnjega obdobja. Dvanajst jih ima rdeči premik najmanj sedem, zato njihova svetloba prihaja iz časa, ko je bilo vesolje mlajše od milijarde let. Rekordna vira z rdečima premikoma 7,77 in 7,69 vidimo približno 670 milijonov let po velikem poku.','Na dejanskih posnetkih niso veliki vrtinci, ampak drobne pike. Osupljiva je njihova svetlost kljub ogromni oddaljenosti. Umetniška slika na vrhu kaže možen pogled od blizu, kolaž v besedilu pa resnične podatke opazovanj. Ilustracije ne smemo zamenjati za fotografijo objekta.']},
        {h:'Kaj je kvazar?',p:['V središču mnogih galaksij je supermasivna črna luknja. Plin na poti vanjo tvori vroč disk in oddaja izjemno veliko svetlobe. Takšno zelo svetlo aktivno galaktično jedro imenujemo kvazar. Ne vidimo same črne luknje, temveč snov okoli nje.','Kvazarji so svetilniki zgodnjega vesolja. Njihova svetloba je potovala milijarde let, zato je pogled na zelo oddaljen kvazar tudi pogled v preteklost. Rdeči premik pove, koliko se je prostor v tem času razširil. Ne pove pa, da je objekt danes še v istem stanju.']},
        {h:'Zakaj so zgodnji kvazarji uganka?',p:['Če je črna luknja že po nekaj sto milijonih let postala tako masivna, je morala nastati iz nečesa in nato hitro pridobivati snov. Astronomi proučujejo različne možnosti: velike začetne zametke, hitro dotekanje plina ali kombinacijo procesov. Večji vzorec omogoča boljši preizkus modelov.','Nova objava sama ne razreši nastanka prvih supermasivnih črnih lukenj. Za oceno mase in okolice potrebujemo spektroskopijo in nadaljnja opazovanja. Znanost napreduje, ko nenavadno najdbo spremenimo v merljive preizkuse več možnih razlag.']},
        {h:'Kako so jih našli?',p:['Evklid pregleduje velika območja neba in poišče kandidate po razporeditvi njihove svetlobe med valovnimi dolžinami. Obetavne objekte nato preverjajo z dodatnimi meritvami. Kombinacija širokega pregleda in natančne potrditve lahko najde redke objekte, ki bi jih ozko vidno polje hitro spregledalo.']}]},
      en:{slug:'euclid-finds-quasars-from-the-young-universe',title:'Euclid finds quasars from the universe’s youth',lead:'The European telescope identified 31 early quasars, including two seen about 670 million years after the Big Bang. Their light raises questions about how black holes grew so fast.',take:['Euclid identified 31 early quasars.','The two most distant have redshifts of 7.77 and 7.69.','We see them as they were about 670 million years after the Big Bang.'],term:'Redshift — the stretching of light’s wavelength as the universe expands; it helps estimate a source’s distance in space and time.',sections:[
        {h:'What did Euclid find?',p:['The Euclid space telescope, built to survey the large-scale universe, found 31 quasars from its early history. Twelve have redshift of at least seven, meaning their light comes from when the universe was younger than a billion years. Two record sources, at redshifts 7.77 and 7.69, are seen as they were roughly 670 million years after the Big Bang.','In real observations they look like tiny points, not giant science-fiction whirlpools. Their brightness at such distances is remarkable. The top image is an artist’s impression of how a quasar might appear up close; the collage below contains actual observation data. Keeping illustration and measurement distinct matters.']},
        {h:'What is a quasar?',p:['Many galaxies contain a supermassive black hole at their center. Gas falling toward it forms a hot disk before crossing the black hole’s boundary and emits enormous light. An exceptionally bright active galactic nucleus is called a quasar. We see the matter around the black hole, not the black hole itself.','Quasars are beacons of the early universe. Their light has travelled for billions of years, so viewing a distant quasar is also looking into the past. Redshift indicates how much space expanded meanwhile. It does not tell us that the object remains in the same state today.']},
        {h:'Why are early quasars puzzling?',p:['If a black hole became very massive within the first few hundred million years, it needed a starting point and a way to gain matter quickly. Astronomers consider several explanations: large initial seeds, exceptionally rapid feeding or a combination. A sample of 31 objects gives them more examples against which to test their models.','This discovery alone does not solve how the first supermassive black holes formed. Spectra and further observations are needed to estimate their masses and surroundings. Science moves forward when a remarkable find becomes a measurable test of competing explanations.']},
        {h:'How were they found?',p:['Euclid scans wide areas of sky and selects candidates from the distribution of their light across wavelengths. Promising objects are then checked with more detailed measurements. Combining a broad search with careful confirmation can reveal rare objects that narrow telescope views might miss.']}]}},
    ['kvazari','crne rupe','Euklid']),
  N('mars-polar-cliffs','space','2026-09-16','mars-swirls',
    [['European Space Agency — Mars Express','https://www.esa.int/Science_Exploration/Space_Science/Mars_Express/Purple_swirls_on_the_Red_Planet']],
    {credit:'ESA/DLR/FU Berlin; CC BY-SA 3.0 IGO',source:'https://www.esa.int/ESA_Multimedia/Images/2026/09/Raspberry_ripples_near_Mars_s_south_pole',license:esaLicence,
      alt:{sr:'Šaroliki reljef Marsa kod južnog pola, sa tamnim krivudavim slojevima.',sl:'Pisana pokrajina Marsa blizu južnega pola s temnimi vijugastimi plastmi.',en:'Colorful Martian landscape near the south pole with dark winding layers.'},
      caption:{sr:'Oblast Thyles Rupes blizu južnog pola Marsa na snimku Mars Expressa iz februara 2026.',sl:'Območje Thyles Rupes blizu južnega pola Marsa na posnetku Mars Expressa iz februarja 2026.',en:'Thyles Rupes near Mars’s south pole, imaged by Mars Express in February 2026.'},
      inline:'news/mars-topography.jpg',inlineCredit:'ESA/DLR/FU Berlin; CC BY-SA 3.0 IGO',inlineSource:'https://www.esa.int/ESA_Multimedia/Images/2026/09/Topographic_map_of_Thyles_Rupes_on_Mars',inlineLicense:esaLicence,
      inlineAlt:{sr:'Topografska karta strmih padina oblasti Thyles Rupes na Marsu.',sl:'Topografski zemljevid strmih pobočij območja Thyles Rupes na Marsu.',en:'Topographic map of steep slopes at Thyles Rupes on Mars.'},
      inlineCaption:{sr:'Topografska karta bojama prikazuje razlike u visini, koje obična fotografija teže otkriva.',sl:'Topografski zemljevid z barvami prikazuje višinske razlike, ki jih fotografija težje razkrije.',en:'The topographic map uses color to show elevation differences that are harder to see in a photograph.'}},
    {
      sr:{slug:'ljubicasti-vrtlozi-kod-juznog-pola-marsa',title:'Zašto Mars kod južnog pola izgleda ljubičasto i naborano?',lead:'Nova slika letelice Mars Express otkriva strme litice, naslage prašine i mraza u oblasti Thyles Rupes. Neobična boja govori o svetlosti i površini, a ne o životu.',take:['Mars Express je snimio oblast Thyles Rupes 17. februara 2026.','Neke litice su više od jednog kilometra.','Ljubičasti ton nastaje kombinacijom boja površine, mraza i obrade snimka.'],term:'Topografska karta — prikaz visine terena koji otkriva oblike reljefa i kada ih fotografija sakrije.',sections:[
        {h:'Šta se vidi na novom snimku?',p:['Evropska letelica Mars Express snimila je 17. februara 2026. područje Thyles Rupes blizu Marsovog južnog pola. Na prikazu se smenjuju svetli i tamni pojasovi, a rubovi visoravni formiraju litice visoke više od jednog kilometra. Fotografija izgleda gotovo kao apstraktna slika, ali svaki zavoj predstavlja stvarnu promenu u sastavu, osvetljenju ili obliku površine.','Nije reč o jednom jedinstvenom materijalu. Svetlije delove mogu prekrivati prašina i mraz ugljen-dioksida; tamniji delovi sadrže mineralne čestice koje slabije odbijaju svetlost. Ugao pod kojim Sunce osvetljava teren i način sastavljanja više kanala kamere utiču na boje prikaza. Ljubičasta nijansa zato nije dokaz nekog neobičnog biološkog procesa.']},
        {h:'Kako nastaju slojevi i litice?',p:['Polarne oblasti Marsa menjaju se sa godišnjim dobima. U hladnim periodima ugljen-dioksid iz atmosfere taloži se kao mraz, a u toplijim se vraća u gas. Vetar prenosi tamnu prašinu i taloži je u udubljenjima ili je uklanja sa viših površina. Tokom mnogo ciklusa takvi procesi mogu naglasiti različite slojeve i stvoriti pruge koje kamera vidi.','Strmi obodi pokazuju gde je teren odsečen erozijom ili geološkim pomeranjima. Jedan snimak ne može samostalno da odredi potpunu istoriju nastanka. Naučnici zato porede fotografiju sa visinskom kartom, ranijim snimcima i podacima o sastavu tla. Kada se isti oblik vidi na više načina, tumačenje je pouzdanije.']},
        {h:'Šta dodaje visinska karta?',p:['Uz fotografiju objavljujemo i topografsku kartu oblasti. Na njoj boje ne pokazuju prirodnu boju Marsa, već visinu. Takva karta pomaže da razlikujemo tamni materijal u dolini od senke na strmoj padini. Takođe otkriva koliko se reljef naglo spušta i u kom pravcu se pružaju grebeni.','Mars Expressova kamera HRSC može snimati područje iz više uglova tokom prolaska letelice. Iz razlika između pogleda nastaje model reljefa, sličan načinu na koji naša dva oka procenjuju dubinu. Tek povezivanjem boje, oblika i visine istraživači dobijaju bolju sliku procesa na površini.']},
        {h:'Zašto je ovo važno?',p:['Iako fotografija nije vest o novoj misiji na površini, ona obogaćuje kartu polarnih predela Marsa. Slojevi mogu sačuvati tragove promene klime i kretanja mraza kroz vreme. Da bismo ih pravilno pročitali, potrebni su mnogi snimci i provera različitih mogućih uzroka. Naučno pitanje nije samo „koja je ovo boja”, već „koji procesi su je stvorili”.']}]},
      sl:{slug:'vijolicni-vzorci-pri-juznem-polu-marsa',title:'Zakaj je Mars ob južnem polu videti vijoličen in naguban?',lead:'Nova slika sonde Mars Express razkriva strme pečine, prah in slano v območju Thyles Rupes. Nenavadna barva govori o svetlobi in površju, ne o življenju.',take:['Mars Express je območje Thyles Rupes posnel 17. februarja 2026.','Nekatere pečine presegajo kilometer višine.','Vijolični videz je povezan s površino, slano, osvetlitvijo in obdelavo posnetka.'],term:'Topografski zemljevid — prikaz nadmorske višine, ki razkrije relief tudi tam, kjer ga fotografija skriva.',sections:[
        {h:'Kaj vidimo na novem posnetku?',p:['Evropska sonda Mars Express je 17. februarja 2026 posnela območje Thyles Rupes blizu južnega pola Marsa. Na sliki se menjajo svetli in temni pasovi, robovi planot pa tvorijo več kot kilometer visoke pečine. Fotografija je videti kot abstraktna umetnina, vendar vsak zavoj pomeni resnično spremembo sestave, osvetlitve ali oblike tal.','Ne gre za en sam material. Svetlejše dele lahko prekrivata prah in slana ogljikovega dioksida, temnejši pa vsebujejo minerale, ki odbijajo manj svetlobe. Kot Sonca in sestavljanje več kanalov kamere vplivata na barve prikaza. Vijolični odtenek zato ni znak nenavadnega biološkega dogajanja.']},
        {h:'Kako nastanejo plasti in pečine?',p:['Marsova pola se spreminjata z letnimi časi. V mrazu se ogljikov dioksid iz ozračja nalaga kot slana, v toplejšem obdobju pa spet postane plin. Veter prenaša temen prah, ga odlaga v kotanjah ali odnaša z višjih predelov. Številni takšni cikli lahko poudarijo plasti in ustvarijo pasove, ki jih zazna kamera.','Strmi robovi kažejo, kje sta teren oblikovali erozija ali geološka zgodovina. En sam posnetek ne razkrije vsega nastanka. Raziskovalci zato fotografijo primerjajo z višinskim zemljevidom, starejšimi posnetki in podatki o sestavi površja. Razlaga je trdnejša, če enako obliko potrdijo različne meritve.']},
        {h:'Kaj doda višinski zemljevid?',p:['Ob fotografiji objavljamo topografski zemljevid. Njegove barve niso naravne barve Marsa, ampak označujejo višino. Tako laže ločimo temen material v dolini od sence na strmem pobočju. Zemljevid pokaže tudi nenaden padec površja in smer grebenov.','Kamera HRSC na sondi Mars Express lahko območje med preletom opazuje iz različnih zornih kotov. Razlike med pogledi omogočijo model reliefa, podobno kot naši očesi ocenjujeta globino. Skupaj barva, oblika in višina razkrijejo več o procesih na površju.']},
        {h:'Zakaj je pomembno?',p:['Posnetek dopolnjuje karto polarnih pokrajin Marsa. Plasti lahko ohranijo sledove sprememb podnebja in gibanja slane skozi čas. Za pravilno razumevanje potrebujemo več podob in primerjavo možnih vzrokov. Znanstveno vprašanje ni le, katera barva je to, temveč kateri procesi so jo ustvarili.']}]},
      en:{slug:'purple-swirls-near-mars-south-pole',title:'Why does Mars look purple and rippled near its south pole?',lead:'A new Mars Express image reveals steep cliffs, dust and frost at Thyles Rupes. The unusual color tells us about light and surface materials, not life.',take:['Mars Express imaged Thyles Rupes on 17 February 2026.','Some cliffs rise more than a kilometer.','The purple appearance reflects surface materials, frost, lighting and image processing.'],term:'Topographic map — a height map that reveals landforms even when a photograph obscures them.',sections:[
        {h:'What does the new image show?',p:['Europe’s Mars Express spacecraft photographed Thyles Rupes near the Martian south pole on 17 February 2026. Light and dark bands wind across the scene, while plateau edges form cliffs over a kilometer high. It looks almost like abstract art, yet each curve reflects real changes in surface composition, lighting or shape.','The scene is not one uniform substance. Brighter areas may include dust and carbon-dioxide frost; darker patches contain minerals that reflect less light. The angle of sunlight and the way camera channels are combined also affect the displayed colors. The purple hue is therefore not evidence of a biological process.']},
        {h:'How do layers and cliffs form?',p:['Martian polar regions change with the seasons. In cold periods carbon dioxide from the air settles as frost; in warmer periods it becomes gas again. Wind moves dark dust, depositing it in hollows or removing it from higher ground. Repeated cycles can emphasize layers and create bands visible from orbit.','Steep edges show where erosion or geological history has cut across the terrain. One image alone cannot establish the complete sequence. Scientists compare the photograph with a height map, older pictures and data on surface composition. An interpretation grows stronger when several kinds of observation show the same feature.']},
        {h:'What does the height map add?',p:['The topographic map accompanying this story uses colors for elevation, not Mars’s natural colors. It helps distinguish dark material in a valley from a shadow on a steep slope. It also shows how abruptly the terrain drops and which direction ridges run.','Mars Express’s HRSC camera views the surface from several angles during a pass. Differences between those views can build a model of relief, much as our two eyes estimate depth. Combining color, shape and height yields a fuller picture of the processes shaping the surface.']},
        {h:'Why is it useful?',p:['The image adds detail to maps of Mars’s polar landscapes. Layers may preserve clues about past climate and the movement of frost over time. Reading those clues correctly requires many observations and tests of possible causes. The scientific question is not just which color we see, but which processes made it.']}]}},
    ['Mars','reljef','sateliti']),
];
